package live.linghe.privateinput;
import java.io.*;import java.util.*;
/** Actual ARM Rime and exact product first-publication recall; no App data/network/UI. */
public final class CliRepeatedCheck {
 static int checks;static long session;static InputQuality quality;static long worstMicros;
 static void require(boolean ok,String reason){checks++;if(!ok)throw new AssertionError(reason);}
 static String[][] type(String raw,boolean slow)throws Exception{NativeCore.mode(session,true,true);for(char c:raw.toCharArray()){NativeCore.key(session,c);String[][] state=NativeCore.snapshot(session);require(state[0][1].isEmpty(),"key cannot auto-commit literal or guessed intent");if(slow)Thread.sleep(12);}return NativeCore.snapshot(session);}
 static List<InputQuality.Repair> first(String raw,String[][] state){long began=System.nanoTime();List<InputQuality.Repair> found=InputQuality.immediateRepeatedHeads(session,state,true);worstMicros=Math.max(worstMicros,(System.nanoTime()-began)/1000);require(NativeCore.draft(session)[0].equals(raw),"recall preserves all raw keys");return found;}
 static Set<String> texts(List<InputQuality.Repair> rows){Set<String> out=new HashSet<>();for(InputQuality.Repair row:rows)out.add(row.text);return out;}
 public static void main(String[] args)throws Exception{session=NativeCore.create(args[0],args[1]);require(session!=0,"init");quality=new InputQuality(new File(args[2]));try{
  for(String raw:new String[]{"4","44","444","4444","44444426","44426","444999999"}){String[][] state=type(raw,false);List<InputQuality.Repair> repairs=first(raw,state);if(raw.equals("4")){require(state.length>1,"single key has native candidates");continue;}require(repairs.size()>1,"ambiguous repeats retain multiple choices");Map<String,InputQuality.Repair> plans=new HashMap<>();String[][] merged=InputQuality.mergeImmediateRepeated(state,repairs,plans);require(merged.length>2,"first published batch is not empty");require(!NativeCore.readableDraft(session,merged[1][2]).matches(".*(?:ghi|abc|mno|wxyz).*"),"readable marked text never expands keyboard groups");Set<String> fast=texts(repairs);state=type(raw,true);require(fast.equals(texts(first(raw,state))),"fast and slow input produce same alternatives");NativeCore.key(session,32);state=NativeCore.snapshot(session);require(state[0][1].isEmpty()&&state[0][2].equals(raw),"unmatched native space cannot commit raw or discard keys");
   InputQuality.Repair selected=repairs.get(0);String[] accepted=NativeCore.commitAlternative(session,raw,selected.spelling,selected.text,selected.remainder);require(accepted.length==2&&accepted[1].equals(selected.text),"explicit chosen repair commits exact text");session=Long.parseLong(accepted[0]);require(NativeCore.draft(session)[0].equals(selected.remainder),"partial selection retains every unmatched tail key");require(NativeCore.snapshot(session)[0][1].isEmpty(),"no duplicate native output");
  }
  String[][] state=type("4444",false);NativeCore.delete(session);require(NativeCore.draft(session)[0].equals("444"),"delete retracts one key");require(first("444",NativeCore.snapshot(session)).size()>1,"delete keeps repeat alternatives");String before=NativeCore.draft(session)[0];require(NativeCore.commitAlternative(session,"stale","ha ha ha","哈哈哈","").length==0&&NativeCore.draft(session)[0].equals(before),"stale decision leaves input untouched");NativeCore.clear(session);state=NativeCore.snapshot(session);require(state[0][1].isEmpty()&&state[0][2].isEmpty(),"focus cancellation never commits literal");NativeCore.mode(session,false,true);for(char c:"hhhh".toCharArray())NativeCore.key(session,c);state=NativeCore.snapshot(session);require(InputQuality.immediateRepeatedHeads(session,state,false).isEmpty(),"Chinese26 not routed to nine repetition policy");require(state[0][1].isEmpty(),"26no automatic literal");System.out.println("PASS assertions="+checks+" actualArmRime=true firstPublishedRecall=true worstRecallMicros="+worstMicros+" network=false installedData=false UI=false");
 }finally{NativeCore.destroy(session);}}
}
